import {APP,LIMITS} from './config.js';
import {DB} from './db.js';
import {ERR,RecordError} from './errors.js';
import {createZip,parseZipStore,textMember} from './zip.js';
import {sha256Bytes,sha256Text,stableStringify,timingSafeEqualText,uuid} from './crypto.js';
import {validateAuditEvent,validateDerivedAsset,validateGame,validateRecognitionEnvelope,validateRecognitionJob,validateReconstructionRun,validateSourcePage} from './validators.js';
import {invalidateCertification,nowIso,verifyCertification} from './record.js';

const ext=m=>m==='image/png'?'png':m==='image/webp'?'webp':'jpg';
const SAFE_SETTING_IDS=new Set(['lastBackupAt','gatewayPreferences','originCutoverReceipt','legacyFoundationMigrationReceipt']);
const encoder=new TextEncoder();

export async function estimateBackup(){const snap=await DB.snapshot();let bytes=0;for(const p of snap.sourcePages||[])bytes+=p.size||p.blob?.size||0;for(const a of snap.derivedAssets||[])bytes+=a.size||a.blob?.size||0;return {sourceBytes:bytes,games:snap.games?.length||0,files:(snap.sourcePages?.length||0)+(snap.derivedAssets?.length||0)};}
function validateUnique(items,key,label){const seen=new Set();for(const x of items||[]){const v=x?.[key];if(seen.has(v))throw new RecordError(ERR.IMP_ARCHIVE,`Duplicate ${label}: ${v}`);seen.add(v);}return seen;}
function splitObsRef(ref){const i=String(ref).indexOf(':');return i>0?[ref.slice(0,i),ref.slice(i+1)]:[null,null];}
export function validateSnapshot(snap){
  if(!snap||typeof snap!=='object'||Array.isArray(snap))throw new RecordError(ERR.IMP_ARCHIVE,'Backup snapshot must be an object.');
  const arrays=['games','sourcePages','derivedAssets','recognitionJobs','recognitionObservations','reconstructionRuns','auditEvents','settings'];for(const k of arrays)if(snap[k]!==undefined&&!Array.isArray(snap[k]))throw new RecordError(ERR.IMP_ARCHIVE,`Backup snapshot ${k} must be an array.`);
  for(const g of snap.games||[])validateGame(g);for(const p of snap.sourcePages||[])validateSourcePage(p);for(const a of snap.derivedAssets||[])validateDerivedAsset(a);for(const j of snap.recognitionJobs||[])validateRecognitionJob(j);for(const o of snap.recognitionObservations||[])validateRecognitionEnvelope(o);for(const r of snap.reconstructionRuns||[])validateReconstructionRun(r);for(const a of snap.auditEvents||[])validateAuditEvent(a);
  const gameIds=validateUnique(snap.games||[],'id','game ID'),pageIds=validateUnique(snap.sourcePages||[],'id','source page ID'),assetIds=validateUnique(snap.derivedAssets||[],'id','derived asset ID'),jobIds=validateUnique(snap.recognitionJobs||[],'id','recognition job ID'),obsIds=validateUnique(snap.recognitionObservations||[],'requestId','recognition request ID');validateUnique(snap.reconstructionRuns||[],'id','reconstruction run ID');validateUnique(snap.auditEvents||[],'id','audit event ID');
  const obsById=new Map((snap.recognitionObservations||[]).map(o=>[o.requestId,o]));
  const byGame=new Map();for(const p of snap.sourcePages||[]){if(!gameIds.has(p.gameId))throw new RecordError(ERR.IMP_ARCHIVE,'Source page references a missing game.');const arr=byGame.get(p.gameId)||[];arr.push(p);byGame.set(p.gameId,arr);}for(const pages of byGame.values()){pages.sort((a,b)=>a.order-b.order);pages.forEach((p,i)=>{if(p.order!==i)throw new RecordError(ERR.IMP_ARCHIVE,'Backup source page order is not canonical.');});}
  for(const a of snap.derivedAssets||[])if(!gameIds.has(a.gameId)||!pageIds.has(a.sourcePageId))throw new RecordError(ERR.IMP_ARCHIVE,'Derived asset references missing evidence.');
  for(const j of snap.recognitionJobs||[])if(!gameIds.has(j.gameId)||!pageIds.has(j.pageId))throw new RecordError(ERR.IMP_ARCHIVE,'Recognition job references missing evidence.');
  for(const o of snap.recognitionObservations||[]){if(!gameIds.has(o.gameId)||!pageIds.has(o.pageId)||!assetIds.has(o.derivedAsset.id))throw new RecordError(ERR.IMP_ARCHIVE,'Recognition observation references missing evidence.');if(jobIds.has(o.requestId)){const j=(snap.recognitionJobs||[]).find(x=>x.id===o.requestId);if(j.gameId!==o.gameId||j.pageId!==o.pageId||j.runSequence!==o.runSequence)throw new RecordError(ERR.IMP_ARCHIVE,'Recognition observation/job binding mismatch.');}}
  for(const r of snap.reconstructionRuns||[]){if(!gameIds.has(r.gameId))throw new RecordError(ERR.IMP_ARCHIVE,'Reconstruction references missing game.');for(const id of r.observationRequestIds)if(!obsIds.has(id))throw new RecordError(ERR.IMP_ARCHIVE,'Reconstruction references missing observation.');}
  for(const e of snap.auditEvents||[])if(!gameIds.has(e.gameId))throw new RecordError(ERR.IMP_ARCHIVE,'Audit event references a missing game.');
  for(const g of snap.games||[])for(const m of g.moves){for(const pid of m.sourceRefs)if(!pageIds.has(pid)||!(snap.sourcePages||[]).some(p=>p.id===pid&&p.gameId===g.id))throw new RecordError(ERR.IMP_ARCHIVE,'Move source reference is dangling or cross-game.');for(const ref of m.observationRefs){const [rid,cid]=splitObsRef(ref),env=obsById.get(rid);if(!env||env.gameId!==g.id||!env.cells.some(c=>c.id===cid))throw new RecordError(ERR.IMP_ARCHIVE,'Move observation reference is dangling or cross-game.');}}
  for(const s of snap.settings||[])if(!s||typeof s.id!=='string'||!SAFE_SETTING_IDS.has(s.id))throw new RecordError(ERR.IMP_ARCHIVE,`Backup contains a non-allowlisted setting: ${s?.id}`);
  return true;
}

async function assertFits(snapshot){let payload=0;for(const p of snapshot.sourcePages||[])payload+=p.size||0;for(const a of snapshot.derivedAssets||[])payload+=a.size||0;if(payload>LIMITS.backupArchiveBytes*0.80)throw new RecordError(ERR.EXP_BACKUP,`Backup binary evidence (${Math.ceil(payload/1024/1024)} MiB) exceeds the conservative in-memory safety budget for this release. Export individual Capsules or reduce the local archive first.`);}
export async function buildBackupFromSnapshot(snapshot){
  validateSnapshot(snapshot);await assertFits(snapshot);const snap=structuredClone(snapshot),files=[],serialized={...snap,sourcePages:[],derivedAssets:[],settings:(snap.settings||[]).filter(s=>SAFE_SETTING_IDS.has(s.id))};
  for(const p of snapshot.sourcePages||[]){const bytes=new Uint8Array(await p.blob.arrayBuffer()),actual=await sha256Bytes(bytes);if(bytes.length!==p.size||!timingSafeEqualText(actual,p.sha256))throw new RecordError(ERR.EXP_BACKUP,`Source integrity failed before backup: ${p.id}`);const path=`blobs/source/${p.gameId}/${p.id}.${ext(p.mime)}`;files.push({name:path,data:bytes});serialized.sourcePages.push({...p,blob:undefined,blobPath:path});}
  for(const a of snapshot.derivedAssets||[]){const bytes=new Uint8Array(await a.blob.arrayBuffer()),actual=await sha256Bytes(bytes);if(bytes.length!==a.size||!timingSafeEqualText(actual,a.sha256))throw new RecordError(ERR.EXP_BACKUP,`Derived integrity failed before backup: ${a.id}`);const path=`blobs/derived/${a.gameId}/${a.id}.${ext(a.mime)}`;files.push({name:path,data:bytes});serialized.derivedAssets.push({...a,blob:undefined,blobPath:path});}
  const payload={schema:APP.backupSchema,backupId:uuid(),createdAt:new Date().toISOString(),snapshot:serialized};files.push({name:'record-backup.json',data:JSON.stringify(payload,null,2)});const desc=[];for(const f of files){const data=f.data instanceof Uint8Array?f.data:encoder.encode(f.data);desc.push({path:f.name,size:data.length,sha256:await sha256Bytes(data)});}desc.sort((a,b)=>a.path.localeCompare(b.path));const manifest={schema:'record-backup-manifest/3',backupId:payload.backupId,createdAt:payload.createdAt,rootHash:await sha256Text(stableStringify(desc)),files:desc};files.push({name:'manifest.json',data:JSON.stringify(manifest,null,2)});return {bytes:createZip(files,{deterministic:true,maxBytes:LIMITS.backupArchiveBytes}),manifest};
}
export async function buildBackup(){return buildBackupFromSnapshot(await DB.snapshot());}

export async function parseBackup(bytes){
  const files=parseZipStore(bytes,{maxBytes:LIMITS.backupArchiveBytes});let manifest,payload;try{manifest=JSON.parse(textMember(files,'manifest.json'));payload=JSON.parse(textMember(files,'record-backup.json'));}catch(error){throw new RecordError(ERR.IMP_ARCHIVE,'Backup JSON could not be parsed.',{cause:String(error)});}if(manifest.schema!=='record-backup-manifest/3'||payload.schema!==APP.backupSchema||manifest.backupId!==payload.backupId)throw new RecordError(ERR.IMP_ARCHIVE,'Backup manifest/payload schema mismatch.');if(!Array.isArray(manifest.files)||manifest.files.length>LIMITS.archiveFiles)throw new RecordError(ERR.IMP_ARCHIVE,'Backup manifest file list invalid.');
  const seen=new Set(),desc=[];for(const d of manifest.files){if(!d||typeof d!=='object'||Array.isArray(d)||Object.keys(d).some(k=>!['path','size','sha256'].includes(k))||typeof d.path!=='string'||d.path.length>LIMITS.archivePathLength||seen.has(d.path)||!Number.isInteger(d.size)||d.size<0||!/^[a-f0-9]{64}$/i.test(String(d.sha256||'')))throw new RecordError(ERR.IMP_ARCHIVE,'Backup manifest descriptor invalid.');seen.add(d.path);const data=files.get(d.path);if(!data)throw new RecordError(ERR.IMP_ARCHIVE,`Backup member missing: ${d.path}`);const hash=await sha256Bytes(data);if(!timingSafeEqualText(hash,d.sha256)||data.length!==d.size)throw new RecordError(ERR.IMP_ARCHIVE,`Backup member integrity failed: ${d.path}`);desc.push({path:d.path,size:data.length,sha256:hash});}
  const expected=new Set(['manifest.json',...manifest.files.map(d=>d.path)]);if(files.size!==expected.size||[...files.keys()].some(n=>!expected.has(n)))throw new RecordError(ERR.IMP_ARCHIVE,'Backup contains an unmanifested member.');desc.sort((a,b)=>a.path.localeCompare(b.path));if(!timingSafeEqualText(await sha256Text(stableStringify(desc)),manifest.rootHash))throw new RecordError(ERR.IMP_ARCHIVE,'Backup root hash mismatch.');const snap=payload.snapshot;
  snap.sourcePages=(snap.sourcePages||[]).map(p=>{const data=files.get(p.blobPath);if(!data)throw new RecordError(ERR.IMP_ARCHIVE,`Source blob missing: ${p.blobPath}`);const x={...p,blob:new Blob([data],{type:p.mime})};delete x.blobPath;return x;});snap.derivedAssets=(snap.derivedAssets||[]).map(a=>{const data=files.get(a.blobPath);if(!data)throw new RecordError(ERR.IMP_ARCHIVE,`Derived blob missing: ${a.blobPath}`);const x={...a,blob:new Blob([data],{type:a.mime})};delete x.blobPath;return x;});validateSnapshot(snap);
  for(const p of snap.sourcePages||[]){const data=new Uint8Array(await p.blob.arrayBuffer());if(data.length!==p.size||!timingSafeEqualText(await sha256Bytes(data),p.sha256))throw new RecordError(ERR.IMP_ARCHIVE,`Backup source digest does not match source descriptor: ${p.id}`);}for(const a of snap.derivedAssets||[]){const data=new Uint8Array(await a.blob.arrayBuffer());if(data.length!==a.size||!timingSafeEqualText(await sha256Bytes(data),a.sha256))throw new RecordError(ERR.IMP_ARCHIVE,`Backup derived digest does not match derived descriptor: ${a.id}`);}return {manifest,payload,snapshot:snap};
}

function remapPayload(value,idMap){if(Array.isArray(value))return value.map(v=>remapPayload(v,idMap));if(value&&typeof value==='object'){const out={};for(const [k,v] of Object.entries(value))out[k]=remapPayload(v,idMap);return out;}return typeof value==='string'&&idMap.has(value)?idMap.get(value):value;}
function remapObsRef(ref,idMap){const [r,c]=splitObsRef(ref);return r?`${idMap.get(r)||r}:${c}`:ref;}
export function cloneSnapshotAsCopies(snapshot){
  validateSnapshot(snapshot);const out=structuredClone(snapshot),idMap=new Map();
  // Pass 1: allocate every identity before any reference is rewritten.
  for(const g of out.games||[])idMap.set(g.id,uuid());for(const p of out.sourcePages||[])idMap.set(p.id,uuid());for(const a of out.derivedAssets||[])idMap.set(a.id,uuid());for(const j of out.recognitionJobs||[])idMap.set(j.id,uuid());for(const o of out.recognitionObservations||[])if(!idMap.has(o.requestId))idMap.set(o.requestId,uuid());for(const r of out.reconstructionRuns||[])idMap.set(r.id,uuid());for(const e of out.auditEvents||[])idMap.set(e.id,uuid());
  for(const g of out.games||[]){g.id=idMap.get(g.id);g.moves=g.moves.map(m=>({...m,sourceRefs:m.sourceRefs.map(x=>idMap.get(x)||x),observationRefs:m.observationRefs.map(x=>remapObsRef(x,idMap))}));invalidateCertification(g,'RESTORED_AS_COPY');g.revision++;g.updatedAt=nowIso();g.flags.needsReview=true;}
  for(const p of out.sourcePages||[]){p.gameId=idMap.get(p.gameId);p.id=idMap.get(p.id);p.updatedAt=nowIso();}
  for(const a of out.derivedAssets||[]){a.gameId=idMap.get(a.gameId);a.sourcePageId=idMap.get(a.sourcePageId);a.id=idMap.get(a.id);}
  for(const j of out.recognitionJobs||[]){j.id=idMap.get(j.id);j.gameId=idMap.get(j.gameId);j.pageId=idMap.get(j.pageId);j.supersedesRequestId=j.supersedesRequestId?(idMap.get(j.supersedesRequestId)||j.supersedesRequestId):null;j.status='CANCELLED';j.lastError='Imported as copy; recognition job cancelled.';j.updatedAt=nowIso();}
  for(const o of out.recognitionObservations||[]){o.requestId=idMap.get(o.requestId);o.gameId=idMap.get(o.gameId);o.pageId=idMap.get(o.pageId);o.supersedesRequestId=o.supersedesRequestId?(idMap.get(o.supersedesRequestId)||o.supersedesRequestId):null;o.derivedAsset.id=idMap.get(o.derivedAsset.id);o.signature='';o.gateway={...o.gateway,build:`${o.gateway.build} / imported-copy`,keyId:'IMPORTED_COPY_UNVERIFIED',signedAt:nowIso()};}
  for(const r of out.reconstructionRuns||[]){r.id=idMap.get(r.id);r.gameId=idMap.get(r.gameId);r.observationRequestIds=r.observationRequestIds.map(x=>idMap.get(x)||x);r.status='STALE';r.selectedPath=null;for(const p of r.paths)for(const m of p.moves){m.sourceRefs=m.sourceRefs.map(x=>idMap.get(x)||x);m.observationRefs=m.observationRefs.map(x=>remapObsRef(x,idMap));}r.updatedAt=nowIso();}
  for(const e of out.auditEvents||[]){e.id=idMap.get(e.id);e.gameId=idMap.get(e.gameId);e.payload=remapPayload(e.payload,idMap);}out.settings=[];validateSnapshot(out);return out;
}

export async function reverifySnapshotCertifications(snapshot){
  for(const g of snapshot.games||[]){if(!g.certification)continue;const pages=(snapshot.sourcePages||[]).filter(p=>p.gameId===g.id),obs=(snapshot.recognitionObservations||[]).filter(o=>o.gameId===g.id);const v=await verifyCertification(g,pages,obs);if(v.status!=='VALID'){invalidateCertification(g,`RESTORE_${v.status}`);g.flags.needsReview=true;g.updatedAt=nowIso();}}
  validateSnapshot(snapshot);return snapshot;
}
export async function restoreBackup(bytes,{conflict='KEEP_LOCAL'}={}){const parsed=await parseBackup(bytes);let snapshot=conflict==='IMPORT_AS_COPY'?cloneSnapshotAsCopies(parsed.snapshot):structuredClone(parsed.snapshot);if(conflict!=='IMPORT_AS_COPY')snapshot=await reverifySnapshotCertifications(snapshot);await DB.restoreSnapshot(snapshot,{conflict:conflict==='IMPORT_AS_COPY'?'KEEP_LOCAL':conflict});return {...parsed,restoredSnapshot:snapshot};}
